/**
 * Sub-issue tree rules shared by the service layer.
 *
 * A root issue sits at level 0; nothing may sit deeper than
 * `MAX_SUB_ISSUE_DEPTH`, and the tree never loops.
 */

export type IssueHierarchyViolation = "cycle" | "too_deep";

/** Raised when placing an issue would loop the tree or nest it too deeply. */
export class IssueHierarchyError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: string,
    readonly reason: IssueHierarchyViolation,
  ) {
    super(
      reason === "cycle"
        ? `Issue ${issueId} cannot be placed under itself or one of its sub-issues.`
        : `Issue ${issueId} cannot be nested that deeply.`,
    );
    this.name = "IssueHierarchyError";
  }
}
EOF
