/** Re-parents one issue; `null` makes it a root issue again. */
export async function setIssueParent(
  orgId: OrgId,
  issueId: IssueId,
  parentId: IssueId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ parentId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);

  const labels = await listLabelsForIssues(orgId, [issueId]);
  return toIssue(row, (labels[issueId] ?? []).map((label) => label.id));
}

/** Direct sub-issues of one issue, oldest first (creation time, then number). */
export async function listSubIssues(
  orgId: OrgId,
  parentId: IssueId,
  scope: ArchiveScope = {},
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.parentId, parentId),
          livePredicate(issues.archivedAt, scope),
        ),
      ),
    )
    .orderBy(asc(issues.createdAt), asc(issues.number))
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );
  return rows.map((row) =>
    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

/** One issue below another, with its level relative to that ancestor (child = 1). */
export interface IssueDescendant {
  readonly issue: Issue;
  readonly depth: number;
}

/**
 * Every issue below `issueId` at any depth, archived ones included, walked
 * breadth-first one level per query. A visited set guards against bad data.
 */
export async function listDescendants(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueDescendant[]> {
  const db = getDb();
  const visited = new Set<string>([issueId]);
  const result: IssueDescendant[] = [];
  let frontier: string[] = [issueId];
  let depth = 0;

  while (frontier.length > 0) {
    depth += 1;
    const rows = db
      .select()
      .from(issues)
      .where(
        and(orgPredicate(issues.orgId, orgId), inArray(issues.parentId, frontier)),
      )
      .all();

    const next: string[] = [];
    for (const row of rows) {
      if (visited.has(row.id)) continue;
      visited.add(row.id);
      next.push(row.id);
      result.push({ issue: toIssue(row), depth });
    }
    frontier = next;
  }

  return result;
}

/** The chain of issues above `issueId`, nearest parent first. */
export async function listAncestors(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const db = getDb();
  const visited = new Set<string>([issueId]);
  const result: Issue[] = [];
  let current = db
    .select()
    .from(issues)
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .get();

  while (current?.parentId && !visited.has(current.parentId)) {
    visited.add(current.parentId);
    current = db
      .select()
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          eq(issues.id, current.parentId),
        ),
      )
      .get();
    if (current) result.push(toIssue(current));
  }

  return result;
}
EOF
