/**
 * A parent must be a live issue of the same project. Issues of another
 * project are reported as missing rather than leaking their existence.
 */
async function requireLiveParent(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const parent = await issueRepo.findIssueById(orgId, parentId);
  if (parent === null || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
  assertNotArchived("Issue", parent.id, parent);
  return parent;
}

/**
 * Places an issue under a parent, moves it under another, or (with a `null`
 * parent) makes it a root issue again. Its sub-issues move with it, so depth
 * is judged by where the deepest live descendant would land.
 */
export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  if (input.parentId !== null) {
    const parent = await requireLiveParent(
      input.orgId,
      issue.projectId,
      input.parentId,
    );

    const descendants = await issueRepo.listDescendants(input.orgId, issue.id);
    if (
      parent.id === issue.id ||
      descendants.some(({ issue: below }) => below.id === parent.id)
    ) {
      throw new IssueHierarchyError(issue.id, "cycle");
    }

    const parentLevel = (await issueRepo.listAncestors(input.orgId, parent.id))
      .length;
    const subtreeDepth = Math.max(
      0,
      ...descendants
        .filter(({ issue: below }) => isLive(below))
        .map(({ depth }) => depth),
    );
    if (parentLevel + 1 + subtreeDepth > MAX_SUB_ISSUE_DEPTH) {
      throw new IssueHierarchyError(issue.id, "too_deep");
    }
  }

  if (issue.parentId === input.parentId) return issue;

  const after = await issueRepo.setIssueParent(
    input.orgId,
    issue.id,
    input.parentId,
