import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
import * as svc from "@/server/services/issue-service";
import { listNotifications } from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());
it("works", async () => {
  const t = await createTenant("sub", "growth");
  const a = t.actors.member;
  const mk = (title: string, parentId: any = null) => svc.createIssue(a, { ...issueInput(t.org.id, t.project.id, { title }), parentId });
  const p = await mk("parent");
  await svc.assignIssue(t.actors.owner, { orgId: t.org.id, issueId: p.id, assigneeId: t.userIds.admin });
  const c1 = await mk("child1", p.id);
  const c2 = await mk("child2", p.id);
  const g = await mk("grand", c1.id);
  const gg = await mk("ggrand", g.id);
  await expect(mk("too deep", gg.id)).rejects.toMatchObject({ reason: "too_deep" });
  await expect(svc.setIssueParent(a, { orgId: t.org.id, issueId: p.id, parentId: g.id })).rejects.toMatchObject({ reason: "cycle" });
  await expect(svc.setIssueParent(a, { orgId: t.org.id, issueId: c1.id, parentId: c2.id })).rejects.toMatchObject({ reason: "too_deep" });
  expect((await svc.listSubIssues(a, t.org.id, p.id)).map((i) => i.title)).toEqual(["child1", "child2"]);
  expect(await svc.getIssueRollup(a, t.org.id, p.id)).toEqual({ total: 4, open: 4, closed: 0 });
  await svc.changeIssueStatus(a, { orgId: t.org.id, issueId: c2.id, status: "done" });
  await svc.archiveIssue(t.actors.owner, t.org.id, c1.id);
  expect(await svc.getIssueRollup(a, t.org.id, p.id)).toEqual({ total: 1, open: 0, closed: 1 });
  const n = await listNotifications(t.actors.owner, { orgId: t.org.id, recipientId: t.userIds.admin, unreadOnly: false, kind: ["sub_issues_completed"], limit: 25, cursor: null });
  expect(n.items).toHaveLength(1);
});
EOF
